"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { modLoad, modCompat, type ModLoad, type Compat } from "./mod-load";
import { installSupport } from "./mod-install-support";

/**
 * Mod-manager actions.
 *
 * Customers browse the per-game mod/plugin CATALOG (GameMod) and one-click
 * install/uninstall onto their server. Each change writes the desired state to a
 * `ServerMod` row (INSTALLING / REMOVING) and enqueues a single GAME_MOD_SYNC job
 * that reconciles the server to that state — the same state-driven pattern as
 * GAME_CONFIG (worker reads the DB, no per-op payloads to trust).
 *
 * Ownership + the "one in-flight job per server" invariant mirror
 * lib/actions-game-config.ts.
 */

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

export type CatalogMod = {
  id: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  url: string | null;
  description: string | null;
  iconUrl: string | null;
  paid: boolean;
  featured: boolean;
  appliesToVariant: string | null;
  /** install state for THIS server: null = not installed. */
  status: string | null;
  error: string | null;
  /* ── verified upstream facts (scripts/verify-gamemods.ts) ──────────────
     Every one of these is read from the mod's own source. Where a source
     doesn't publish something it stays null/empty and the panel says so,
     rather than filling the gap with a plausible-looking number. */
  downloads: number | null;
  fileBytes: number | null;
  dependencyCount: number;
  impact: string;
  impactNote: string | null;
  verified: boolean;
  compat: Compat;
  /** Null when one-click install works; the reason it doesn't, otherwise. */
  manualInstall: string | null;
};

export type ModsView = {
  family: string;
  variant: string | null;
  /** catalog entries (compatible with the server's variant), grouped by category. */
  categories: { category: string; mods: CatalogMod[] }[];
  installedCount: number;
  busy: boolean;
  /** The version this server is pinned to, when its game has one. */
  gameVersion: string | null;
  /** What the installed set is asking of this server. */
  load: ModLoad;
};

/**
 * Load the mod catalog for an owned game server, annotated with each mod's
 * install state on this server. Only mods for the server's game family and
 * compatible with its selected variant are returned.
 */
export async function getServerMods(
  serverId: string
): Promise<{ error?: string; view?: ModsView }> {
  const { server } = await ownedServer(serverId);
  const family = familyFor(server);
  if (!family) return { error: "This server doesn't support mods." };

  const variant = server.gameVariant ?? null;
  /* The pinned game version lives in the per-family config blob under VERSION
     (a docker env var for the Minecraft images, not a server.properties key —
     see lib/game-config.ts). Families without one simply have no verdict. */
  const cfg = (server.gameConfig ?? null) as Record<string, unknown> | null;
  const rawVersion = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
  // "LATEST"/"SNAPSHOT" name a moving target, not a version we can match against.
  const gameVersion = rawVersion && !/^(latest|snapshot)$/i.test(rawVersion) ? rawVersion : null;

  const [catalog, installed, busy] = await Promise.all([
    db.gameMod.findMany({
      // A project that no longer resolves upstream would fail on install, so it
      // is not offered — see scripts/verify-gamemods.ts.
      where: { gameFamily: family, active: true, upstreamOk: true },
      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
    }),
    db.serverMod.findMany({ where: { serverId } }),
    hasInflightJob(serverId),
  ]);

  const stateByMod = new Map(installed.map((m) => [m.modId, m]));

  // Hide mods that target a different loader/variant than the server runs.
  const compatible = catalog.filter(
    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
  );

  const byCategory = new Map<string, CatalogMod[]>();
  for (const m of compatible) {
    const st = stateByMod.get(m.id);
    const row: CatalogMod = {
      id: m.id,
      name: m.name,
      slug: m.slug,
      category: m.category,
      source: m.source,
      url: m.url,
      description: m.description,
      iconUrl: m.iconUrl,
      paid: m.paid,
      featured: m.featured,
      appliesToVariant: m.appliesToVariant,
      status: st?.status ?? null,
      error: st?.error ?? null,
      downloads: m.downloads,
      fileBytes: m.fileBytes,
      dependencyCount: m.dependencyCount,
      impact: m.impact,
      impactNote: m.impactNote,
      verified: m.verifiedAt !== null,
      manualInstall: (() => {
        const sup = installSupport(family, m.source);
        return sup.ok ? null : sup.message;
      })(),
      compat: modCompat(
        { gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide },
        { gameVersion, variant },
      ),
    };
    const arr = byCategory.get(m.category) ?? [];
    arr.push(row);
    byCategory.set(m.category, arr);
  }

  const categories = [...byCategory.entries()]
    .map(([category, mods]) => ({ category, mods }))
    .sort((a, b) => a.category.localeCompare(b.category));

  const live = installed.filter((m) => m.status === "INSTALLED" || m.status === "INSTALLING");
  const byId = new Map(catalog.map((m) => [m.id, m]));
  const load = modLoad({
    // The game plan is what the customer bought and what sizes the VM; the base
    // plan only backs it. Falling back to 0 would claim a 0 GB server, so an
    // unknown size means no ratio rather than a wrong one.
    ramMB: server.gamePlan?.ramMB ?? 0,
    installed: live.map((s) => {
      const m = byId.get(s.modId);
      return { name: m?.name ?? "Unknown mod", fileBytes: m?.fileBytes ?? null, impact: m?.impact ?? "light" };
    }),
  });

  return {
    view: { family, variant, categories, installedCount: live.length, busy, gameVersion, load },
  };
}

/** Queue a mod for install on an owned server. */
export async function installMod(
  serverId: string,
  modId: string
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);
  const family = familyFor(server);
  if (!family) return { error: "This server doesn't support mods." };

  const mod = await db.gameMod.findUnique({ where: { id: modId } });
  if (!mod || !mod.active) return { error: "That mod is unavailable." };
  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
  }

  /* Refuse here rather than queue a GAME_MOD_SYNC that can only come back
     "auto-install isn't wired for this game". The panel already hides the
     button for these, so reaching this is a stale page or a direct call — but
     an unrunnable job would still take the server's one in-flight slot. */
  const support = installSupport(family, mod.source);
  if (!support.ok) return { error: support.message };

  const existing = await db.serverMod.findUnique({
    where: { serverId_modId: { serverId, modId } },
  });
  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
    return { error: `${mod.name} is already installed.` };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.serverMod.upsert({
    where: { serverId_modId: { serverId, modId } },
    create: { serverId, modId, status: "INSTALLING", error: null },
    update: { status: "INSTALLING", error: null },
  });
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/** Queue a mod for removal from an owned server. */
export async function uninstallMod(
  serverId: string,
  modId: string
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const existing = await db.serverMod.findUnique({
    where: { serverId_modId: { serverId, modId } },
    include: { mod: true },
  });
  if (!existing || existing.status === "REMOVED") {
    return { error: "That mod isn't installed." };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.serverMod.update({
    where: { serverId_modId: { serverId, modId } },
    data: { status: "REMOVING", error: null },
  });
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "gameserver.mod.uninstall", detail: `${serverId} mod=${existing.mod.slug}` },
  });

  void server; // ownership already enforced above
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/**
 * Whether a catalogue entry can actually be installed with one click.
 *
 * WHY THIS IS ITS OWN MODULE. Two independent things have to both be true, and
 * until now neither was checked before the button was drawn:
 *
 *   1. the worker knows WHERE this game keeps its mods
 *      (worker/game-mods.ts's `modDirShell`), and
 *   2. the worker can turn this entry's source into a DOWNLOAD URL
 *      (worker/game-mods.ts's `resolveUrl`).
 *
 * The catalogue is far wider than either. Expanding it from 124 entries across
 * five games to 491 across eight made that gap much bigger rather than smaller:
 * every Factorio, Satisfactory, Palworld, CS2 and V Rising entry got an Install
 * button that reaches the worker and comes back "Auto-install isn't wired for
 * this game yet." A button whose only outcome is an error is worse than no
 * button, and it is worse again at 178 of them.
 *
 * So the two lists live here, `worker/game-mods.ts` imports them rather than
 * keeping its own copies, and the panel asks the same question before it
 * decides what to render. One source of truth, so the UI and the worker cannot
 * disagree about what is possible.
 *
 * ADDING A FAMILY is deliberately a two-part job: add its directory to
 * `modDirShell` AND its slug here. Adding it here alone re-creates exactly the
 * failure this module exists to prevent.
 */

/** Families whose mod directory `worker/game-mods.ts` knows how to find. */
export const INSTALLABLE_FAMILIES = new Set(["minecraft", "rust", "valheim"]);

/** Sources `worker/game-mods.ts` can resolve to a downloadable file. */
export const RESOLVABLE_SOURCES = new Set(["modrinth", "spigotmc", "umod", "thunderstore"]);

export type InstallSupport =
  | { ok: true }
  | { ok: false; reason: "family" | "source"; message: string };

/**
 * Can this entry be installed for the customer, or does it have to be done by
 * hand? The message is customer-facing and says which of the two is missing,
 * because they lead to different next steps: a family we can't reach means
 * upload it yourself, a source we can't fetch from means download it first.
 */
export function installSupport(family: string, source: string): InstallSupport {
  if (!INSTALLABLE_FAMILIES.has(family)) {
    return {
      ok: false,
      reason: "family",
      message: "We can't place files for this game automatically yet — install it yourself in Files.",
    };
  }
  if (!RESOLVABLE_SOURCES.has(source)) {
    return {
      ok: false,
      reason: "source",
      message: "This source doesn't offer a direct download we can fetch — grab the file and upload it in Files.",
    };
  }
  return { ok: true };
}

import type { NextConfig } from "next";

// Content-Security-Policy: moderate, integration-aware. Uses 'unsafe-inline'
// (no nonce infra yet) but still adds real protections — object-src none,
// base-uri/form-action self, frame-ancestors none, and script/frame allowlists
// for Stripe + analytics. connect-src is permissive to keep the console (wss)
// and API integrations working.
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  // PayPal's JS SDK (loaded by @paypal/react-paypal-js on the embedded Payment
  // step) both executes a script from paypal.com/paypalobjects.com AND opens an
  // in-page iframe from the same origins for the button + approval flow — found
  // by actually loading the page in a real browser (Playwright) during the
  // embedded-payment-UI build, where the button silently failed to render with
  // nothing but a CSP violation in the console. Sandbox's domain is included too
  // so a `PAYPAL_MODE=sandbox` testing session isn't the ONE environment this
  // never got exercised in.
  "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://plausible.io https://*.googletagmanager.com https://www.google-analytics.com https://js.stripe.com https://www.paypal.com https://www.paypalobjects.com https://www.sandbox.paypal.com",
  "connect-src 'self' https: wss:",
  // blob: lets the webmail render an email body in a sandboxed blob:-URL iframe
  // (a `srcdoc` frame loads as about:srcdoc, which this frame-src refuses). The
  // frame stays fully sandboxed and inherits the rest of this CSP.
  "frame-src 'self' blob: https://js.stripe.com https://hooks.stripe.com https://www.paypal.com https://www.sandbox.paypal.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  "upgrade-insecure-requests",
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Content-Type-Options", value: "nosniff" },
  // NOTE: X-Frame-Options is intentionally NOT set here — nginx already sends it,
  // and two conflicting values (DENY vs SAMEORIGIN) is undefined behaviour.
  // CSP `frame-ancestors 'none'` above is the authoritative, stricter control.
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // microphone=(self): the Matrix build console offers voice-to-text (Web Speech
  // API), which the browser gates on the microphone permission policy. A bare
  // microphone=() disables the mic for the whole origin, so the mic button did
  // nothing at all. (self) grants it to our own pages only — third-party frames
  // still can't use it. camera/geolocation stay fully disabled (never used).
  { key: "Permissions-Policy", value: "camera=(), microphone=(self), geolocation=(), interest-cohort=()" },
  { key: "X-DNS-Prefetch-Control", value: "on" },
];

const nextConfig: NextConfig = {
  // The dev overlay sits bottom-left, exactly on top of the sidebar's account
  // balance card, which makes the design impossible to compare against the
  // reference. Sandbox only — prod never sets NXEON_SANDBOX.
  ...(process.env.NXEON_SANDBOX === "1" ? { devIndicators: false as const } : {}),
  output: "standalone",
  // ssh2 (and its SFTP wrapper) ship an OPTIONAL native addon (sshcrypto.node).
  // When the toolchain is present at install time npm builds that binary, and
  // webpack then fails trying to parse it into the server bundle. These are
  // server-only modules, so mark them external — Next require()s them at runtime
  // instead of bundling, which is the correct treatment for a native addon and
  // is behaviour-neutral (falls back to ssh2's pure-JS crypto when unbuilt).
  // pdfkit resolves its built-in font metrics (`js/data/*.afm`) relative to its
  // own file location. Bundled, that becomes `.next/server/chunks/data/` — which
  // no build ever writes — so every emailed invoice lost its PDF with
  // `ENOENT ... chunks/data/Helvetica.afm` while the email itself still sent.
  // External keeps the require at runtime, so it finds its own data dir. Same
  // reason geoip-lite is here: a package that reads data files off its own path
  // cannot be bundled.
  // playwright is here for the same reason: it resolves its browser binaries off
  // its own installation path at runtime (~/.cache/ms-playwright), so bundling it
  // breaks the lookup. It is `await import()`ed, and only ever from the hosting
  // website-preview capture (lib/hosting-thumb.ts) — nothing on a request path
  // loads it, so an environment with no browser installed simply fails that one
  // task with a real error instead of affecting the app.
  serverExternalPackages: ["@prisma/client", "bcryptjs", "ssh2", "ssh2-sftp-client", "geoip-lite", "pdfkit", "playwright"],
  experimental: {
    // Webmail attachments travel through a Server Action as base64, and Next's
    // default Server Action body limit is 1 MB. Base64 inflates by ~4/3, so
    // anything over roughly 700 KB was rejected by the framework before our
    // handler ever ran — while both the composer
    // (components/customer/mail/Composer.tsx) and the server
    // (lib/actions-mail.ts MAX_ATTACHMENTS_TOTAL_BYTES) advertised 20 MB.
    // Customers attached a 2 MB PDF and the mail silently failed to send.
    // 20 MB of files encodes to ~26.7 MB; 30 MB leaves headroom for the rest of
    // the payload (recipients, subject, HTML body). lib/actions-mail.ts still
    // enforces the real 20 MB cap, with a message the customer can act on.
    serverActions: { bodySizeLimit: "30mb" },
    // Same class of bug as the serverActions limit above, a different layer:
    // middleware.ts's matcher covers virtually every path (including
    // /api/files/[serverId]'s upload route), and Next.js caps the request
    // body it will forward THROUGH middleware at 10MB by default —
    // independent of both nginx's client_max_body_size and the route
    // handler's own MAX_UPLOAD_BYTES check, which never even got a chance to
    // run: the body was already truncated to 10MB before either of those
    // layers saw it. Found live 2026-09-06 via a real production log line
    // ("Request body exceeded 10MB for /api/files/...") after nginx's size
    // limit and client_body_timeout were both already fixed and still didn't
    // resolve the customer's upload failure — this was the actual, complete
    // cause. Matches the app's own 250MB upload limit + margin.
    middlewareClientMaxBodySize: "260mb",
  },
  async headers() {
    // Static image assets under /public default to `max-age=0` (revalidate on
    // every request) — fine for an app served from a CDN edge, but this origin
    // has no CDN in front of it (confirmed: nxeon.cloud resolves straight to
    // the single origin IP, no proxy). Every visitor everywhere round-trips to
    // this one box for the logo on every single page load. Confirmed live from
    // this host: 20ms — but a customer's round-trip from another continent is
    // a different story, and a multi-region browsing check surfaced the logo
    // failing to render in some locations, consistent with a slow/uncached
    // image request timing out on a long-haul connection. These filenames only
    // change via a deploy (new build = new deploy = fine to cache hard);
    // `immutable` tells the browser to skip revalidation entirely for the
    // whole max-age window instead of asking the origin on every load.
    const longCache = [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }];
    return [
      { source: "/:path*", headers: securityHeaders },
      { source: "/logo.png", headers: longCache },
      { source: "/nx-mark.png", headers: longCache },
      { source: "/games/art/:path*", headers: longCache },
      { source: "/logos/:path*", headers: longCache },
    ];
  },
  async redirects() {
    return [
      // The RevSports venture page was retired. 301 to home so any indexed URL or
      // stray inbound link lands somewhere real instead of 404-ing.
      { source: "/revsports", destination: "/", permanent: true },

