/** Decode the handful of HTML entities the agents emitted. &amp; is decoded LAST
 *  so a double-encoded "&amp;lt;" resolves to "&lt;" not "<". */
function decode(s) {
  if (typeof s !== "string") return s;
  return s
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&#x2F;/gi, "/")
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&");
}

function decodePost(p) {
  const out = { ...p };
  for (const k of ["title", "excerpt", "seoTitle", "seoDescription", "body"]) {
    if (typeof out[k] === "string") out[k] = decode(out[k]);
  }
  if (Array.isArray(out.tags)) out.tags = out.tags.map(decode);
  return out;
}

/** Pull the last assistant text block out of an agent's JSONL transcript. */
function lastAssistantText(file) {
  const lines = readFileSync(`${TASK_DIR}/${file}`, "utf8").split("\n").filter(Boolean);
  let text = null;
  for (const line of lines) {
    let obj;
    try { obj = JSON.parse(line); } catch { continue; }
    const content = obj?.message?.content;
    if (obj?.type === "assistant" && Array.isArray(content)) {
      const t = content.filter((c) => c?.type === "text").map((c) => c.text).join("");
      if (t.trim()) text = t;
    }
  }
  return text;
}

/** Extract the JSON array of posts from an agent's final message. */
function postsFromFile(file) {
  const raw = lastAssistantText(file);
  if (!raw) throw new Error(`no assistant text in ${file}`);
  // strip ```json fences if present, then take the outermost [ ... ]
  let s = raw.replace(/```json\s*/gi, "").replace(/```/g, "").trim();
  const start = s.indexOf("[");
  const end = s.lastIndexOf("]");
  if (start === -1 || end === -1) throw new Error(`no JSON array in ${file}`);
  const arr = JSON.parse(s.slice(start, end + 1));
  if (!Array.isArray(arr)) throw new Error(`not an array in ${file}`);
  return arr;
}

