/**
 * Verify every seeded GameMod row against its real upstream source and write
 * back the facts the catalogue/install UI needs: iconUrl, downloads, license,
 * gameVersions, loaders, fileBytes, dependencyCount, serverSide, impact,
 * impactNote, verifiedAt, upstreamOk (+ upstreamNote).
 *
 * WHY THIS EXISTS. Every one of those fields has sat null/zero/true (the
 * default) on all 124 seeded rows since the catalogue was seeded — nothing in
 * this repo ever populated them. `lib/actions-mods.ts` and
 * `components/customer/gamepanel/v2/ModsPanel.tsx` both already read them and
 * both already say, in their own comments, that this script is what fills
 * them in. It also doubles as the "mark as no longer supported" mechanism the
 * owner asked for: re-running this periodically flips `upstreamOk` to false
 * (with a human-readable `upstreamNote`) the moment a project disappears
 * upstream, and the catalogue (getServerMods, and the public NxLabs pages)
 * already filter on `upstreamOk`.
 *
 * SOURCES COVERED THIS PASS: modrinth, spigotmc (via the public Spiget API),
 * thunderstore — the same three `worker/game-mods.ts` already knows how to
 * install from (RESOLVABLE_SOURCES in lib/mod-install-support.ts), so "we can
 * verify it" and "we can install it" track the same source list on purpose.
 * umod / github / nexus / codefling are deliberately left alone here — none of
 * them has a lightweight, well-documented "give me this exact project's
 * metadata by id" endpoint the way the three above do (umod.org has no public
 * read API at all; GitHub/Nexus would need per-repo/per-file heuristics with
 * real risk of wrong data). Their rows simply keep verifiedAt: null, which the
 * UI already renders as "unverified" rather than a fabricated tick — see
 * ModsPanel.tsx's comment on exactly this. Wiring those up is real, separate
 * follow-up work, not a blocker for shipping the majority (58 of 124 rows).
 *
 * IDEMPOTENT + RE-RUNNABLE: safe to run on a cron. Every write is a fresh
 * fetch-and-overwrite of the verified fields for that one row; nothing here
 * depends on the previous state except to compare for the summary counts.
 *
 * Run:  cd /opt/nxeon && npx tsx scripts/verify-gamemods.ts [--source=modrinth] [--limit=20]
 */
import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mod-verify; +https://nxeon.cloud)";
const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";

type VerifyResult =
  | {
      ok: true;
      iconUrl: string | null;
      downloads: number | null;
      license: string | null;
      gameVersions: string[];
      loaders: string[];
      fileBytes: number | null;
      dependencyCount: number;
      serverSide: string | null;
    }
  | { ok: false; note: string };

/** light | moderate | heavy from real file size, plus a customer-facing note for the heavier tiers. */
function impactFromBytes(bytes: number | null): { impact: string; impactNote: string | null } {
  if (!bytes || bytes <= 0) return { impact: "light", impactNote: null };
  const mb = bytes / (1024 * 1024);
  if (mb >= 60) {
    return { impact: "heavy", impactNote: `Large download (~${Math.round(mb)} MB) — expect a slower install and a heavier footprint on your plan.` };
  }
  if (mb >= 12) {
    return { impact: "moderate", impactNote: `Medium-sized download (~${Math.round(mb)} MB).` };
  }
  return { impact: "light", impactNote: null };
}

async function verifyModrinth(sourceId: string): Promise<VerifyResult> {
  const headers: Record<string, string> = { "User-Agent": UA };
  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;

  const projRes = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}`, { headers });
  if (projRes.status === 404 || projRes.status === 410) {
    return { ok: false, note: "Removed from Modrinth (project no longer exists)." };
  }
  if (!projRes.ok) return { ok: false, note: `Modrinth API returned ${projRes.status}.` };
  const project = (await projRes.json()) as {
    icon_url?: string | null;
    downloads?: number;
    license?: { id?: string; name?: string };
    game_versions?: string[];
    loaders?: string[];
    server_side?: string;
    status?: string;
  };
  if (project.status && !["approved", "archived", "unlisted"].includes(project.status)) {
    return { ok: false, note: `Modrinth project status is "${project.status}".` };
  }

  let fileBytes: number | null = null;
  let dependencyCount = 0;
  try {
    const verRes = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, { headers });
    if (verRes.ok) {
      const versions = (await verRes.json()) as Array<{
        files: Array<{ url: string; primary: boolean; size?: number }>;
        dependencies?: unknown[];
      }>;
      const latest = versions[0];
      if (latest) {
        const f = latest.files.find((x) => x.primary) ?? latest.files[0];
        fileBytes = f?.size ?? null;
        dependencyCount = latest.dependencies?.length ?? 0;
      }
    }
  } catch {
    /* version lookup is best-effort — project-level facts above still apply */
  }

  return {
    ok: true,
    iconUrl: project.icon_url ?? null,
    downloads: typeof project.downloads === "number" ? project.downloads : null,
    license: project.license?.id || project.license?.name || null,
    gameVersions: project.game_versions ?? [],
    loaders: project.loaders ?? [],
    fileBytes,
    dependencyCount,
    serverSide: project.server_side ?? null,
  };
}

async function verifySpigotmc(sourceId: string): Promise<VerifyResult> {
  const res = await fetch(`https://api.spiget.org/v2/resources/${encodeURIComponent(sourceId)}`, {
    headers: { "User-Agent": UA },
  });
  if (res.status === 404) return { ok: false, note: "Removed from SpigotMC (resource no longer exists)." };
  if (!res.ok) return { ok: false, note: `Spiget API returned ${res.status}.` };
  const resource = (await res.json()) as {
    downloads?: number;
    testedVersions?: string[];
    icon?: { url?: string };
    file?: { size?: number; sizeUnit?: string };
    existenceStatus?: string;
  };
  if (resource.existenceStatus && resource.existenceStatus !== "EXISTS") {
    return { ok: false, note: `SpigotMC resource status: ${resource.existenceStatus}.` };
  }
  // Spiget's icon.url is relative to spigotmc.org; the file size is reported
  // in whatever unit sizeUnit says (almost always KB) — normalize to bytes.
  const iconUrl = resource.icon?.url ? `https://www.spigotmc.org/${resource.icon.url}` : null;
  const unit = (resource.file?.sizeUnit ?? "KB").toUpperCase();
  const rawSize = resource.file?.size ?? null;
  const fileBytes =
    rawSize == null ? null : unit === "MB" ? Math.round(rawSize * 1024 * 1024) : unit === "GB" ? Math.round(rawSize * 1024 * 1024 * 1024) : Math.round(rawSize * 1024);

  return {
    ok: true,
    iconUrl,
    downloads: typeof resource.downloads === "number" ? resource.downloads : null,
    license: null, // Spiget doesn't publish a license field.
    gameVersions: resource.testedVersions ?? [],
    loaders: [],
    fileBytes,
    dependencyCount: 0,
    serverSide: null, // SpigotMC resources are always server plugins; no client/server split to report.
  };
}

/** Thunderstore's package id in this catalogue is `<namespace>-<name>` (see worker/game-mods.ts's resolveUrl). */
async function verifyThunderstore(sourceId: string): Promise<VerifyResult> {
  const [namespace, ...rest] = sourceId.split("-");
  const name = rest.join("-");
  if (!namespace || !name) return { ok: false, note: `Unrecognized Thunderstore id "${sourceId}".` };

  const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/`, {
    headers: { "User-Agent": UA },
  });
  if (res.status === 404) return { ok: false, note: "Removed from Thunderstore (package no longer exists)." };
  if (!res.ok) return { ok: false, note: `Thunderstore API returned ${res.status}.` };
  const pkg = (await res.json()) as {
    is_deprecated?: boolean;
    latest?: { icon?: string; downloads?: number; dependencies?: unknown[] };
  };
  if (pkg.is_deprecated) {
    return { ok: false, note: "Package is marked deprecated on Thunderstore." };
  }
  return {
    ok: true,
    iconUrl: pkg.latest?.icon ?? null,
    downloads: typeof pkg.latest?.downloads === "number" ? pkg.latest.downloads : null,
    license: null, // Thunderstore's package API doesn't publish a license field.
    // Thunderstore mod-loader packages aren't tagged to specific game versions
    // the way Modrinth projects are — real absence of data, not a bug.
    gameVersions: [],
    loaders: [],
    fileBytes: null, // not exposed by the experimental package endpoint
    dependencyCount: pkg.latest?.dependencies?.length ?? 0,
    serverSide: null,
  };
}

const VERIFIERS: Record<string, (sourceId: string) => Promise<VerifyResult>> = {
  modrinth: verifyModrinth,
  spigotmc: verifySpigotmc,
  thunderstore: verifyThunderstore,
};

async function main() {
  const args = process.argv.slice(2);
  const sourceArg = args.find((a) => a.startsWith("--source="))?.split("=")[1];
  const limitArg = args.find((a) => a.startsWith("--limit="))?.split("=")[1];
  const limit = limitArg ? Number(limitArg) : undefined;

  const sources = sourceArg ? [sourceArg] : Object.keys(VERIFIERS);
  const unsupported = sourceArg && !VERIFIERS[sourceArg];
  if (unsupported) {
    console.error(`No verifier for source "${sourceArg}". Supported: ${Object.keys(VERIFIERS).join(", ")}`);
    process.exit(1);
  }

  const mods = await db.gameMod.findMany({
    where: { source: { in: sources }, sourceId: { not: null } },
    orderBy: [{ gameFamily: "asc" }, { name: "asc" }],
    ...(limit ? { take: limit } : {}),
  });

  console.log(`Verifying ${mods.length} mod(s) across source(s): ${sources.join(", ")}`);

  let verified = 0;
  let failed = 0;
  let skipped = 0;

  for (const mod of mods) {
    const verifier = VERIFIERS[mod.source];
    if (!verifier || !mod.sourceId) {
      skipped++;
      continue;
    }
    try {
      const result = await verifier(mod.sourceId);
      if (result.ok) {
        const { impact, impactNote } = impactFromBytes(result.fileBytes);
        await db.gameMod.update({
          where: { id: mod.id },
          data: {
            iconUrl: result.iconUrl,
            downloads: result.downloads,
            license: result.license,
            gameVersions: result.gameVersions,
            loaders: result.loaders,
            fileBytes: result.fileBytes,
            dependencyCount: result.dependencyCount,
            serverSide: result.serverSide,
            impact,
            impactNote,
            verifiedAt: new Date(),
            upstreamOk: true,
            upstreamNote: null,
          },
        });
        verified++;
        console.log(`  OK    ${mod.gameFamily}/${mod.slug} (${mod.source}) — downloads=${result.downloads ?? "?"} icon=${result.iconUrl ? "yes" : "no"}`);
      } else {
        await db.gameMod.update({
          where: { id: mod.id },
          data: { upstreamOk: false, upstreamNote: result.note, verifiedAt: new Date() },
        });
        failed++;
        console.log(`  DEAD  ${mod.gameFamily}/${mod.slug} (${mod.source}) — ${result.note}`);
      }
    } catch (e) {
      failed++;
      const msg = e instanceof Error ? e.message : String(e);
      console.error(`  ERROR ${mod.gameFamily}/${mod.slug} (${mod.source}): ${msg}`);
    }
    // Be a polite API citizen — small delay between calls, no need to hammer
    // free public endpoints for a 124-row catalogue.
    await new Promise((r) => setTimeout(r, 150));
  }

  const totalCatalog = await db.gameMod.count();
  const stillUnverified = await db.gameMod.count({ where: { verifiedAt: null } });
  console.log(
    `\nDone. verified=${verified} dead=${failed} skipped(no-verifier-or-id)=${skipped}. ` +
      `Catalog total=${totalCatalog}, still unverified (other sources)=${stillUnverified}.`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

