input.content:
/**
 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
 *
 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
 * sites that must never disagree about what a mod "is":
 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
 *   - app/sitemap.ts (which detail pages get indexed)
 *
 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
 *
 * HONESTY: a mod only appears in the public/portal catalogue when
 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
 * excluded rather than shown with a broken badge, matching how
 * lib/actions-mods.ts's getServerMods already filters for the per-server
 * panel. Fields the source never published (gameVersions, license, ...) stay
 * empty and the UI says so — never a guess.
 */
import { db } from "./db";
import type { GameMod, GamePlan } from "@prisma/client";
import { GAME_DISPLAY, type GameFamily } from "./games";

export type ModSummary = {
  id: string;
  gameFamily: string;
  gameFamilyLabel: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  iconUrl: string | null;
  description: string | null;
  downloads: number | null;
  featured: boolean;
  paid: boolean;
  verified: boolean;
  impact: string;
};

export type ModDetail = ModSummary & {
  url: string | null;
  license: string | null;
  gameVersions: string[];
  loaders: string[];
  fileBytes: number | null;
  dependencyCount: number;
  serverSide: string | null;
  impactNote: string | null;
  appliesToVariant: string | null;
  verifiedAt: Date | null;
  upstreamOk: boolean;
  upstreamNote: string | null;
};

function familyLabel(family: string): string {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

function toSummary(m: GameMod): ModSummary {
  return {
    id: m.id,
    gameFamily: m.gameFamily,
    gameFamilyLabel: familyLabel(m.gameFamily),
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    iconUrl: m.iconUrl,
    description: m.description,
    downloads: m.downloads,
    featured: m.featured,
    paid: m.paid,
    verified: m.verifiedAt !== null,
    impact: m.impact,
  };
}

function toDetail(m: GameMod): ModDetail {
  return {
    ...toSummary(m),
    url: m.url,
    license: m.license,
    gameVersions: m.gameVersions,
    loaders: m.loaders,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    serverSide: m.serverSide,
    impactNote: m.impactNote,
    appliesToVariant: m.appliesToVariant,
    verifiedAt: m.verifiedAt,
    upstreamOk: m.upstreamOk,
    upstreamNote: m.upstreamNote,
  };
}

/** Real, publicly-listable families — active mods with a real upstream today. */
export async function listCatalogFamilies(): Promise<{ family: string; label: string; count: number }[]> {
  const rows = await db.gameMod.groupBy({
    by: ["gameFamily"],
    where: { active: true, upstreamOk: true },
    _count: true,
    orderBy: { gameFamily: "asc" },
  });
  return rows
    .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
    .sort((a, b) => b.count - a.count);
}

/** Browse listing, optionally scoped to one family. Small catalogue (~124 rows) — no pagination needed yet. */
export async function listCatalogMods(family?: string): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
  });
  return rows.map(toSummary);
}

/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true },
    select: { gameFamily: true, slug: true },
  });
  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug }));
}

/** One mod's detail. Returns null for an unknown/inactive slug — callers should notFound(). */
export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
  const row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
  if (!row || !row.active) return null;
  return toDetail(row);
}

/** A handful of other mods in the same family, for "related mods" rails. */
export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
    orderBy: [{ category: mod.category ? undefined : "asc" }, { downloads: "desc" }].filter(Boolean) as never,
    take,
  });
  // Prefer same-category matches first, client-side sort (small result set).
  return rows
    .map(toSummary)
    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category));
}

export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;

/**
 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
 * light-impact mods run on any active plan for the family; moderate needs at
 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
 * for the family that clears the bar, or null if none does (never guesses a
 * number that isn't a real, active, orderable plan).
 */
export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
  const pick = candidates[0];
  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
}

export function formatDownloads(n: number | null): string | null {
  if (n == null) return null;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
  return String(n);
}

export function formatBytes(bytes: number | null): string | null {
  if (!bytes || bytes <= 0) return null;
  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

