"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { getEligibleServersForMod, installMod, type EligibleServer } from "@/lib/actions-mods";

/**
 * "Add to my server" — the one piece of NxLabs that differs between an
 * anonymous visitor and a signed-in customer with a matching server. Used on
 * BOTH the public mod detail page and the logged-in /dashboard/nxlabs page,
 * so the three states (anonymous / no matching server / pick-and-install)
 * only exist once. Installing always goes through the real installMod()
 * server action — nothing here talks to a server directly.
 */
export function AddToServerWidget({ modId, gameFamily, downloadUrl }: { modId: string; gameFamily: string; downloadUrl: string | null }) {
  const [loading, setLoading] = useState(true);
  const [loggedIn, setLoggedIn] = useState(false);
  const [servers, setServers] = useState<EligibleServer[]>([]);
  const [selected, setSelected] = useState<string>("");
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<{ ok?: boolean; error?: string } | null>(null);

  useEffect(() => {
    let cancelled = false;
    getEligibleServersForMod(modId).then((res) => {
      if (cancelled) return;
      setLoggedIn(res.loggedIn);
      setServers(res.servers);
      setSelected(res.servers[0]?.id ?? "");
      setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, [modId]);

  if (loading) {
    return <div className="h-11 w-full animate-pulse rounded-lg bg-white/[0.06]" />;
  }

  if (!loggedIn) {
    return (
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
        <p className="text-sm text-[var(--fg-muted)]">
          <Link href={`/login?next=/mods`} className="text-brand-300 underline underline-offset-2">
            Log in
          </Link>{" "}
          to add this straight to one of your {gameFamily} servers, or download it directly below.
        </p>
      </div>
    );
  }

  if (servers.length === 0) {
    return (
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
        <p className="text-sm text-[var(--fg-muted)]">
          You don&apos;t have a matching {gameFamily} server yet.{" "}
          <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
            Order one
          </Link>{" "}
          to install this in one click next time, or download it directly below.
        </p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.03] p-4">
      <div className="flex flex-wrap items-center gap-3">
        <select
          className="input max-w-xs"
          value={selected}
          onChange={(e) => setSelected(e.target.value)}
          disabled={pending}
        >
          {servers.map((s) => (
            <option key={s.id} value={s.id}>
              {s.label || s.hostname}
            </option>
          ))}
        </select>
        <button
          className="btn-primary"
          disabled={pending || !selected}
          onClick={() =>
            startTransition(async () => {
              setResult(null);
              const res = await installMod(selected, modId);
              setResult(res);
            })
          }
        >
          {pending ? "Adding…" : "Add to my server"}
        </button>
        {downloadUrl && (
          <a href={downloadUrl} className="btn-secondary" target="_blank" rel="noopener noreferrer nofollow">
            Download instead
          </a>
        )}
      </div>
      {result?.ok && <p className="mt-3 text-sm text-emerald-400">Queued — it&apos;ll be installed shortly. Check the server&apos;s Mods tab.</p>}
      {result?.error && <p className="mt-3 text-sm text-red-400">{result.error}</p>}
    </div>
  );
}

import Link from "next/link";
import { formatDownloads, SOURCE_LABEL, type ModSummary } from "@/lib/mods-catalog";

/**
 * One catalogue tile. Plain <img>, not next/image — the icon URLs come from
 * whichever source verified the mod (cdn.modrinth.com, spigotmc.org,
 * gcdn.thunderstore.io, ...), and next/image requires every remote host to be
 * allow-listed up front. The CSP already permits `img-src https:`, so a plain
 * tag renders every one of them with no per-CDN config to maintain as new
 * sources get verified. See next.config.ts's comment on this same decision.
 */
export function ModCard({ mod, href }: { mod: ModSummary; href: string }) {
  const downloads = formatDownloads(mod.downloads);
  return (
    <Link href={href} className="card card-hover group flex flex-col gap-3 p-4">
      <div className="flex items-center gap-3">
        <div className="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-lg border border-white/10 bg-white/[0.04]">
          {mod.iconUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={mod.iconUrl} alt="" width={48} height={48} loading="lazy" className="h-full w-full object-cover" />
          ) : (
            <span className="text-lg font-semibold text-[var(--fg-muted)]">{mod.name.slice(0, 1)}</span>
          )}
        </div>
        <div className="min-w-0 flex-1">
          <h3 className="truncate text-sm font-semibold text-[var(--fg)] group-hover:text-brand-300">{mod.name}</h3>
          <p className="text-xs text-[var(--fg-muted)]">
            {mod.gameFamilyLabel} · {mod.category}
          </p>
        </div>
      </div>
      {mod.description && <p className="line-clamp-2 text-xs leading-relaxed text-[var(--fg-muted)]">{mod.description}</p>}
      <div className="mt-auto flex items-center justify-between text-[11px] text-[var(--fg-muted)]">
        <span>{SOURCE_LABEL[mod.source] ?? mod.source}</span>
        <span className="flex items-center gap-2">
          {downloads && <span>{downloads} downloads</span>}
          {mod.verified && <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-emerald-400">Verified</span>}
        </span>
      </div>
    </Link>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { PageHero, Section, SectionTitle } from "@/components/marketing/primitives";
import { ModCard } from "@/components/mods/ModCard";
import { APP_URL, FaqJsonLd } from "@/components/marketing/StructuredData";
import { listCatalogFamilies, listCatalogMods } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

export async function generateMetadata({
  searchParams,
}: {
  searchParams: Promise<{ family?: string }>;
}): Promise<Metadata> {
  const { family } = await searchParams;
  const title = family
    ? `${family[0].toUpperCase()}${family.slice(1)} Mods & Plugins — NxLabs`
    : "NxLabs — Free Mods, Plugins & Server Add-ons";
  const description = family
    ? `Browse verified ${family} mods and plugins with real download counts, licenses, and version support — download free, or add straight to your Nxeon server.`
    : "NxLabs is Nxeon's free, public mod & plugin catalog — verified against Modrinth, SpigotMC, and Thunderstore. Browse and download with no account required.";
  return {
    title,
    description,
    alternates: { canonical: family ? `/mods?family=${encodeURIComponent(family)}` : "/mods" },
    openGraph: { title, description, type: "website" },
  };
}

const FAQ = [
  {
    q: "Do I need an Nxeon account to download from NxLabs?",
    a: "No. Every mod page links to its real, authoritative source (Modrinth, SpigotMC, or Thunderstore) — anyone can download for free with no account.",
  },
  {
    q: "What does \"Verified\" mean on a mod?",
    a: "Verified mods have been checked live against their source's own API — real download counts, supported game versions, and file size, refreshed periodically so a removed or deprecated project stops being listed.",
  },
  {
    q: "Can I install a mod straight onto my server?",
    a: "If you have an Nxeon game server matching the mod's game, log in and use \"Add to my server\" for a one-click install. Anyone else gets the same direct download link.",
  },
];

export default async function ModsCatalogPage({
  searchParams,
}: {
  searchParams: Promise<{ family?: string }>;
}) {
  const { family } = await searchParams;
  const [families, mods] = await Promise.all([listCatalogFamilies(), listCatalogMods(family)]);
  const totalMods = families.reduce((sum, f) => sum + f.count, 0);

  return (
    <>
      <FaqJsonLd items={FAQ} />
      <PageHero
        eyebrow="NxLabs"
        title="Mods, plugins & server add-ons"
        sub={`${totalMods} verified add-ons for Minecraft, Rust, Valheim, CS2 and Palworld — real download counts, real licenses, and a direct link to the source. Free for anyone, one click if you have a matching Nxeon server.`}
      />
      <Section>
        <div className="mb-8 flex flex-wrap gap-2">
          <Link
            href="/mods"
            className={`rounded-full border px-4 py-1.5 text-sm ${!family ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"}`}
          >
            All ({totalMods})
          </Link>
          {families.map((f) => (
            <Link
              key={f.family}
              href={`/mods?family=${f.family}`}
              className={`rounded-full border px-4 py-1.5 text-sm ${family === f.family ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"}`}
            >
              {f.label} ({f.count})
            </Link>
          ))}
        </div>

        {mods.length === 0 ? (
          <p className="text-sm text-[var(--fg-muted)]">No verified mods for this game yet — check back soon.</p>
        ) : (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
            {mods.map((mod) => (
              <ModCard key={mod.id} mod={mod} href={`/mods/${mod.gameFamily}/${mod.slug}`} />
            ))}
          </div>
        )}
      </Section>
      <Section>
        <SectionTitle title="Frequently asked" />
        <div className="mx-auto mt-6 max-w-2xl divide-y divide-white/10">
          {FAQ.map((f) => (
            <div key={f.q} className="py-4">
              <h3 className="text-sm font-semibold text-[var(--fg)]">{f.q}</h3>
              <p className="mt-1 text-sm text-[var(--fg-muted)]">{f.a}</p>
            </div>
          ))}
        </div>
        <p className="mt-8 text-center text-xs text-[var(--fg-muted)]">
          Running an Nxeon game server? Install any of these in one click from your{" "}
          <Link href="/dashboard/nxlabs" className="text-brand-300 underline underline-offset-2">
            dashboard
          </Link>
          , or read about our built-in{" "}
          <Link href="/game-servers/mods" className="text-brand-300 underline underline-offset-2">
            Mod Store
          </Link>
          .
        </p>
      </Section>
    </>
  );
}

