import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { familyFor } from "@/lib/game-config";
import { PageShell } from "@/components/nx/PageShell";
import { ModCard } from "@/components/mods/ModCard";
import { QuickAddButton, type QuickAddServer } from "@/components/mods/QuickAddButton";
import { listCatalogFamilies, listCatalogMods } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

/**
 * NxLabs, inside the portal — the SAME catalog as the public /mods pages
 * (lib/mods-catalog.ts), with one addition a logged-in customer gets for
 * free: a real, matching server can be added to in one click, right from the
 * grid. Nothing here forks the install path — QuickAddButton calls the same
 * installMod() server action as the per-server Mods tab (ModsPanel.tsx) and
 * the public detail page's AddToServerWidget.
 *
 * This is a dedicated top-level page, not a tab inside GamePanelShell — see
 * lib/nx/nav.ts's NxLabs entry. That per-server tab stays exactly as it is,
 * for managing one server's installed mods; this page is for BROWSING and
 * discovering, the way the public catalog is, just with your own servers
 * already wired in.
 */
export default async function NxLabsPage({
  searchParams,
}: {
  searchParams: Promise<{ family?: string }>;
}) {
  const user = await requireUser();
  const { family } = await searchParams;

  const [families, mods, myServers] = await Promise.all([
    listCatalogFamilies(),
    listCatalogMods(family),
    db.server.findMany({
      where: { userId: user.id, status: { notIn: ["DELETING"] } },
      include: { osTemplate: true, gamePlan: true },
    }),
  ]);

  // One pass over the (small) server list per mod family, so the grid below
  // does zero extra queries — matches getEligibleServersForMod's own rules
  // (family + variant) but computed once for everyone on the page.
  const serversByFamily = new Map<string, QuickAddServer[]>();
  for (const s of myServers) {
    const fam = familyFor(s);
    if (!fam) continue;
    const arr = serversByFamily.get(fam) ?? [];
    arr.push({ id: s.id, hostname: s.hostname, label: s.label });
    serversByFamily.set(fam, arr);
  }

  return (
    <PageShell
      eyebrow="NxLabs"
      title="Mods & plugins"
      sub={`Browse the same verified catalog anyone can — with one-click install for the ${myServers.length ? "servers" : "server"} you own.`}
      tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}
    >
      <div className="mb-6 flex flex-wrap gap-2">
        <Link
          href="/dashboard/nxlabs"
          className={`rounded-full border px-4 py-1.5 text-sm ${!family ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-tx-mute hover:border-white/20"}`}
        >
          All
        </Link>
        {families.map((f) => (
          <Link
            key={f.family}
            href={`/dashboard/nxlabs?family=${f.family}`}
            className={`rounded-full border px-4 py-1.5 text-sm ${family === f.family ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-tx-mute hover:border-white/20"}`}
          >
            {f.label} ({f.count})
          </Link>
        ))}
      </div>

      {mods.length === 0 ? (
        <p className="text-sm text-tx-mute">No verified mods for this game yet.</p>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {mods.map((mod) => {
            const matching = serversByFamily.get(mod.gameFamily) ?? [];
            return (
              <div key={mod.id} className="card flex flex-col gap-3 p-4">
                <ModCard mod={mod} href={`/mods/${mod.gameFamily}/${mod.slug}`} />
                {matching.length > 0 ? (
                  <QuickAddButton modId={mod.id} servers={matching} />
                ) : (
                  <p className="text-xs text-tx-mute">
                    No matching server yet —{" "}
                    <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
                      order one
                    </Link>{" "}
                    or download from the{" "}
                    <Link href={`/mods/${mod.gameFamily}/${mod.slug}`} className="text-brand-300 underline underline-offset-2">
                      mod page
                    </Link>
                    .
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}
    </PageShell>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";

/**
 * Admin controls for the NxLabs catalogue (GameMod).
 *
 * Deliberately thin for Phase 1 — per the owner's ask, this is "view rows,
 * toggle active/see upstreamOk", not a full mod editor. The REAL upstream
 * facts (icon, downloads, license, verifiedAt, upstreamOk/upstreamNote) are
 * never hand-edited here; they only ever come from scripts/verify-gamemods.ts
 * reading the mod's actual source. `active` is the one thing an admin sets by
 * hand — pulling a mod from the catalogue without waiting for (or overriding)
 * a verification pass, e.g. a licensing complaint or a request from the
 * source. Mirrors lib/actions-gameplans.ts's adminToggleGamePlan exactly,
 * with the shared recordAudit() writer instead of an ad hoc db.auditLog.create.
 */

type Result = { error?: string; ok?: boolean };

export async function adminToggleGameModActive(id: string): Promise<Result> {
  const admin = await requireArea("billing");
  const mod = await db.gameMod.findUnique({ where: { id } });
  if (!mod) return { error: "Not found." };
  const next = !mod.active;
  await db.gameMod.update({ where: { id }, data: { active: next } });
  await recordAudit(admin.id, "gamemod.toggle", `${mod.gameFamily}/${mod.slug} → active=${next}`);
  revalidatePath("/admin/game-mods");
  revalidatePath("/mods");
  return { ok: true };
}

/**
 * Explicit "mark as no longer supported" — separate from `active` because the
 * two answer different questions: `active` is "should the catalogue offer
 * this at all", `upstreamOk` is "does the source still have it". An admin
 * flipping this by hand covers the gap between verify runs (a customer
 * reports a dead link today, the next scheduled verify isn't for hours).
 */
export async function adminSetGameModUpstreamOk(id: string, upstreamOk: boolean, note: string): Promise<Result> {
  const admin = await requireArea("billing");
  const mod = await db.gameMod.findUnique({ where: { id } });
  if (!mod) return { error: "Not found." };
  await db.gameMod.update({
    where: { id },
    data: {
      upstreamOk,
      upstreamNote: upstreamOk ? null : note.trim() || "Marked unsupported by an admin.",
      verifiedAt: new Date(),
    },
  });
  await recordAudit(admin.id, "gamemod.upstream", `${mod.gameFamily}/${mod.slug} → upstreamOk=${upstreamOk}`);
  revalidatePath("/admin/game-mods");
  revalidatePath("/mods");
  return { ok: true };
}

"use client";

import { useState, useTransition } from "react";
import { adminToggleGameModActive, adminSetGameModUpstreamOk } from "@/lib/actions-admin-gamemods";

export function ToggleGameModButton({ id, active }: { id: string; active: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
      disabled={pending}
      onClick={() => start(() => adminToggleGameModActive(id))}
    >
      {active ? "Disable" : "Enable"}
    </button>
  );
}

export function MarkUnsupportedButton({ id, upstreamOk }: { id: string; upstreamOk: boolean }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  if (!upstreamOk) {
    return (
      <button
        className="btn-secondary py-1 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const res = await adminSetGameModUpstreamOk(id, true, "");
            setError(res.error ?? null);
          })
        }
      >
        Mark supported again
      </button>
    );
  }

  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          const note = window.prompt("Why is this no longer supported? (shown to customers)", "");
          if (note === null) return;
          setError(null);
          start(async () => {
            const res = await adminSetGameModUpstreamOk(id, false, note);
            setError(res.error ?? null);
          });
        }}
      >
        Mark unsupported
      </button>
    </span>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { formatDownloads, SOURCE_LABEL } from "@/lib/mods-catalog";
import { ToggleGameModButton, MarkUnsupportedButton } from "@/components/admin/GameModControls";

export const dynamic = "force-dynamic";

/**
 * NxLabs catalogue admin — the "view rows, toggle active / mark unsupported"
 * surface the owner asked for. Deliberately NOT a full editor: every verified
 * fact (icon, downloads, license, gameVersions, ...) comes from
 * scripts/verify-gamemods.ts reading the real source, never a hand-typed
 * value here. Grouped + sorted the same way /admin/game-plans is, since it's
 * the sibling entry in the Catalog nav section (lib/admin-groups.ts).
 */
export default async function AdminGameModsPage() {
  await requireArea("billing");

  const mods = await db.gameMod.findMany({
    orderBy: [{ gameFamily: "asc" }, { verifiedAt: "desc" }, { name: "asc" }],
  });

  const byFamily = new Map<string, typeof mods>();
  for (const m of mods) {
    const arr = byFamily.get(m.gameFamily) ?? [];
    arr.push(m);
    byFamily.set(m.gameFamily, arr);
  }

  const totalVerified = mods.filter((m) => m.verifiedAt !== null).length;
  const totalUnsupported = mods.filter((m) => !m.upstreamOk).length;

  return (
    <div>
      <PageHeader
        title="NxLabs mod catalog"
        sub="Every seeded mod/plugin, real verified facts from scripts/verify-gamemods.ts, and the active/unsupported toggles."
      >
        <Badge tone="brand">{mods.length} mods</Badge>
        <Badge tone="green">{totalVerified} verified</Badge>
        {totalUnsupported > 0 && <Badge tone="red">{totalUnsupported} unsupported</Badge>}
      </PageHeader>

      <div className="space-y-8">
        {[...byFamily.entries()].map(([fam, rows]) => (
          <section key={fam}>
            <h2 className="mb-3 flex items-center gap-2 text-lg font-semibold">
              {GAME_DISPLAY[fam as GameFamily]?.name ?? fam}
              <span className="text-sm font-normal text-slate-500">
                {rows.length} mod{rows.length === 1 ? "" : "s"}
              </span>
            </h2>
            <div className="space-y-2">
              {rows.map((m) => (
                <div key={m.id} className="card">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex min-w-0 items-center gap-3">
                      {m.iconUrl ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img src={m.iconUrl} alt="" width={36} height={36} className="h-9 w-9 shrink-0 rounded-md border border-white/10 object-cover" />
                      ) : (
                        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md border border-white/10 bg-white/5 text-xs text-slate-500">
                          {m.name.slice(0, 1)}
                        </div>
                      )}
                      <div className="min-w-0">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="font-semibold text-white">{m.name}</span>
                          {m.featured && <Badge tone="brand">Featured</Badge>}
                          <Badge tone={m.active ? "green" : "slate"}>{m.active ? "Active" : "Disabled"}</Badge>
                          {!m.upstreamOk && <Badge tone="red">Unsupported</Badge>}
                          {!m.verifiedAt && <Badge tone="slate">Unverified</Badge>}
                        </div>
                        <p className="mt-1 text-xs text-slate-400">
                          {m.category} · {SOURCE_LABEL[m.source] ?? m.source} · slug: {m.slug}
                          {m.downloads != null && ` · ${formatDownloads(m.downloads)} downloads`}
                          {m.license && ` · ${m.license}`}
                        </p>
                        {!m.upstreamOk && m.upstreamNote && (
                          <p className="mt-1 text-xs text-red-400">{m.upstreamNote}</p>
                        )}
                        <p className="mt-0.5 text-xs text-slate-500">
                          {m.verifiedAt ? `Verified ${m.verifiedAt.toISOString().slice(0, 10)}` : "Never verified"}
                        </p>
                      </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                      <ToggleGameModButton id={m.id} active={m.active} />
                      <MarkUnsupportedButton id={m.id} upstreamOk={m.upstreamOk} />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}

