import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:8080";

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on("console", (msg) => { if (msg.type() === "error") consoleErrors.push(msg.text()); });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));

  // 1. Public browse page
  await page.goto(`${BASE}/mods`, { waitUntil: "networkidle" });
  const title = await page.title();
  const modLinks = await page.$$eval('a[href^="/mods/"]', (els) => els.map((e) => e.getAttribute("href")).filter((h) => h.split("/").length === 4));
  console.log("BROWSE title:", title);
  console.log("BROWSE mod links found:", modLinks.length, modLinks.slice(0, 5));
  await page.screenshot({ path: "/root/scratch-nxlabs/browse.png", fullPage: false });

  const imgs = await page.$$eval("img", (els) => els.map((e) => ({ src: e.src, w: e.naturalWidth, h: e.naturalHeight })));
  const brokenBrowse = imgs.filter((i) => i.src.includes("modrinth") || i.src.includes("spigot") || i.src.includes("thunderstore")).filter((i) => i.w === 0);
  console.log("BROWSE mod icons:", imgs.filter((i) => i.src.includes("modrinth") || i.src.includes("spigot") || i.src.includes("thunderstore")).length, "broken:", brokenBrowse.length);

  // 2. Two detail pages
  const detailPaths = modLinks.slice(0, 3);
  for (const path of detailPaths.slice(0, 2)) {
