import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";

const BASE = "https://staging.nxeon.cloud";

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on("console", (msg) => { if (msg.type() === "error") consoleErrors.push(msg.text()); });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));
  page.on("response", (res) => { if (res.status() >= 500) consoleErrors.push(`5xx ${res.status()} ${res.url()}`); });

  // 1. Public browse page
  await page.goto(`${BASE}/mods`, { waitUntil: "networkidle" });
  console.log("BROWSE title:", await page.title());
  const modLinks = await page.$$eval('a[href^="/mods/"]', (els) => els.map((e) => e.getAttribute("href")).filter((h) => h.split("/").length === 4));
  console.log("BROWSE mod links found:", modLinks.length);

  // Scroll to force lazy images to load, then check.
  await page.evaluate(async () => {
    for (let y = 0; y < document.body.scrollHeight; y += 400) {
      window.scrollTo(0, y);
      await new Promise((r) => setTimeout(r, 30));
    }
  });
  await page.waitForTimeout(1500);
  const imgs = await page.$$eval("img", (els) => els.map((e) => ({ src: e.src, w: e.naturalWidth })));
  const modIcons = imgs.filter((i) => /modrinth|spigot|thunderstore/.test(i.src));
  console.log("BROWSE mod icons:", modIcons.length, "loaded (w>0):", modIcons.filter((i) => i.w > 0).length, "broken:", modIcons.filter((i) => i.w === 0).length);
  await page.screenshot({ path: "/root/scratch-nxlabs/browse.png" });

  // 2. Two REAL verified (modrinth) detail pages
  const detailPages = ["/mods/minecraft/essentialsx", "/mods/minecraft/luckperms"];
  for (const path of detailPages) {
    await page.goto(`${BASE}${path}`, { waitUntil: "networkidle" });
    await page.waitForTimeout(1200); // let the client AddToServerWidget resolve
    const dTitle = await page.title();
    const dImgs = await page.$$eval("img", (els) => els.map((e) => ({ src: e.src, w: e.naturalWidth })));
    const heroIcon = dImgs.find((i) => /modrinth|spigot|thunderstore/.test(i.src));
    const bodyText = await page.innerText("body");
    console.log(`DETAIL ${path} title:`, dTitle);
    console.log(`DETAIL ${path} hero icon loaded:`, heroIcon ? `${heroIcon.src} w=${heroIcon.w}` : "NONE");
    console.log(`DETAIL ${path} has "Log in" prompt:`, bodyText.includes("Log in"));
    console.log(`DETAIL ${path} has Download link:`, /Download file|View on/.test(bodyText));
    await page.screenshot({ path: `/root/scratch-nxlabs/detail-${path.split("/").pop()}.png` });
  }

  console.log("CONSOLE/5xx ERRORS:", consoleErrors.length ? consoleErrors.slice(0, 15) : "none");
  await browser.close();
}

main().catch((e) => { console.error(e); process.exit(1); });

