import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";

const BASE = "https://staging.nxeon.cloud";
const EMAIL = "nxlabs-e2e-test@nxeon.test";
const PASSWORD = "NxLabsE2E-Test-2026!";

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("response", (res) => { if (res.status() >= 500) errors.push(`5xx ${res.status()} ${res.url()}`); });

  // Log in
  await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
  await page.fill('input[name="email"], input[type="email"]', EMAIL);
  await page.fill('input[name="password"], input[type="password"]', PASSWORD);
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
    page.click('button[type="submit"]'),
  ]);
  console.log("After login URL:", page.url());

  // 1. Dashboard NxLabs page
  await page.goto(`${BASE}/dashboard/nxlabs`, { waitUntil: "networkidle" });
  console.log("NxLabs dashboard title:", await page.title());
  const bodyText1 = await page.innerText("body");
  console.log("Dashboard shows 'NxLabs Test Server' option somewhere:", bodyText1.includes("NxLabs Test Server"));
  console.log("Dashboard shows 'Add to server' button text present:", bodyText1.includes("Add to server"));
  await page.screenshot({ path: "/root/scratch-nxlabs/dashboard-nxlabs.png", fullPage: false });

  // Find EssentialsX card and click its "Add to server" button
  const card = page.locator("text=EssentialsX").first();
  await card.scrollIntoViewIfNeeded();
  const container = page.locator("div", { has: page.locator("text=EssentialsX") }).last();
  await page.screenshot({ path: "/root/scratch-nxlabs/dashboard-essentialsx-area.png" });

  const addButtons = await page.$$('button:has-text("Add to server")');
  console.log("Add to server buttons found on page:", addButtons.length);
  if (addButtons.length > 0) {
    // Click the one nearest EssentialsX: find via evaluate on DOM
    const clicked = await page.evaluate(() => {
      const cards = Array.from(document.querySelectorAll("a[href*='/mods/minecraft/essentialsx']"));
      if (!cards.length) return false;
      const wrapper = cards[0].closest("div.flex.flex-col") || cards[0].parentElement?.parentElement;
      const btn = wrapper?.querySelector("button");
      if (btn) { btn.click(); return true; }
      return false;
    });
    console.log("Clicked EssentialsX Add-to-server button via DOM:", clicked);
    await page.waitForTimeout(2000);
    const bodyText2 = await page.innerText("body");
    console.log("Post-click shows 'Queued for install':", bodyText2.includes("Queued for install"));
  }

  // 2. Public detail page while logged in — should show the select + Add button, not "Log in"
  await page.goto(`${BASE}/mods/minecraft/luckperms`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  const bodyText3 = await page.innerText("body");
  console.log("Public detail page (logged in) has 'Log in' prompt:", bodyText3.includes("Log in to add"));
  console.log("Public detail page (logged in) has server select/Add button:", bodyText3.includes("Add to my server"));
  await page.screenshot({ path: "/root/scratch-nxlabs/detail-loggedin-luckperms.png" });

  console.log("ERRORS:", errors.length ? errors : "none");
  await browser.close();
}

main().catch((e) => { console.error(e); process.exit(1); });

