import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";

const TOKEN = process.argv[2];
const HOST = "staging.4j3d7gkr2wcbi34.nxeon.cloud";
const BASE = `https://${HOST}`;

async function main() {
  const browser = await chromium.launch();
  const ctx = await browser.newContext();
  await ctx.addCookies([
    { name: "nxeon_staging_session", value: TOKEN, domain: HOST, path: "/", httpOnly: true, secure: true },
  ]);
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("response", (res) => { if (res.status() >= 500) errors.push(`5xx ${res.status()} ${res.url()}`); });

  await page.goto(`${BASE}/admin/game-mods`, { waitUntil: "networkidle" });
  console.log("URL:", page.url());
  const text = await page.innerText("body");
  console.log("Snippet:", text.slice(0, 400));
  console.log("Has 'mods' count:", /\d+ mods/.test(text));
  console.log("Has Unverified:", text.includes("Unverified"));
  console.log("Has Unsupported:", text.includes("Unsupported"));
  await page.screenshot({ path: "/root/scratch-nxlabs/admin-game-mods.png" });

  const before = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll(".card"));
    const row = rows.find((r) => r.textContent.includes("EssentialsX"));
    return row ? (row.textContent.includes("Disabled") ? "Disabled" : "Active") : "NOT FOUND";
  });
  console.log("EssentialsX before:", before);

  const clicked = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll(".card"));
    const row = rows.find((r) => r.textContent.includes("EssentialsX"));
    const btn = row ? Array.from(row.querySelectorAll("button")).find((b) => /Disable|Enable/.test(b.textContent)) : null;
    if (btn) { btn.click(); return true; }
    return false;
  });
  console.log("clicked toggle:", clicked);
  await page.waitForTimeout(1500);
  await page.reload({ waitUntil: "networkidle" });
  const after = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll(".card"));
    const row = rows.find((r) => r.textContent.includes("EssentialsX"));
    return row ? (row.textContent.includes("Disabled") ? "Disabled" : "Active") : "NOT FOUND";
  });
  console.log("EssentialsX after toggle+reload:", after);

  // restore
  await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll(".card"));
    const row = rows.find((r) => r.textContent.includes("EssentialsX"));
    const btn = row ? Array.from(row.querySelectorAll("button")).find((b) => /Disable|Enable/.test(b.textContent)) : null;
    if (btn) btn.click();
  });
  await page.waitForTimeout(1000);

  console.log("ERRORS:", errors.length ? errors : "none");
  await browser.close();
}
main().catch((e) => { console.error(e); process.exit(1); });

