const TOKEN = process.argv[2];
const HOST = "staging.4j3d7gkr2wcbi34.nxeon.cloud";
// This admin host's nginx vhost proxies to node-2 (a separate box/deployment,
// per CLAUDE.md's multi-node docs) — not this box's own nxeon-staging-web. The
// session token here is signed for THIS box's DB/AUTH_SECRET, so we bypass
// nginx and hit this box's own staging-web process directly on its port,
// using Chromium's host-resolver-rules so the Host header still reads as the
// admin host (middleware's isAdminHost check needs that, not DNS).
const BASE = `http://${HOST}:3001`;

async function main() {
  const browser = await chromium.launch({ args: [`--host-resolver-rules=MAP ${HOST} 127.0.0.1`] });
  const ctx = await browser.newContext();
  await ctx.addCookies([
    { name: "nxeon_session_stg", value: TOKEN, domain: HOST, path: "/", httpOnly: true, secure: false },
  ]);

